(function() {
    'use strict';

    class QuantResearchAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Investigacion Cuantitativa 616`;
            this.version = `1.1.0`;
            this.ROUNDS = [
                {
                    key: `r1`,
                    nameKey: `round1_name`,
                    briefingKey: `round1_brief`
                },
                {
                    key: `r2`,
                    nameKey: `round2_name`,
                    briefingKey: `round2_brief`
                },
                {
                    key: `r3`,
                    nameKey: `round3_name`,
                    briefingKey: `round3_brief`
                },
                {
                    key: `r4`,
                    nameKey: `round4_name`,
                    briefingKey: `round4_brief`
                }
            ];
            this._briefingWired = false;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    credibility: 100,
                    biasIndex: 0,
                    marketEstimate: 0,
                    budgetUsed: 0,
                    credibilityHistory: [],
                    biasHistory: [],
                    marketHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sampleSize: 1050,
                    onlinePct: 50,
                    neutralQ: `mixed`,
                    weightIncome: 0,
                    nonResponseAdj: `none`,
                    intentionDiscount: 0,
                    method: `B`,
                    growthAssumption: 15,
                    carrefourCapture: 25,
                    recommend: `invest_partial`,
                    confidence: `balanced`,
                    disclosure: `partial`
                };
            }
            var self = this;
            // Drive the briefing/decision panel from the framework lifecycle rather
            // than a fixed-delay timer (fixes the stale-panel-after-Undo bug and the
            // 400ms race against the async period save). See _wireBriefingEvents.
            this._wireBriefingEvents();
            setTimeout(function() { self._updateBriefing(state); self._wireSliderLabels(); }, 100);
        }

        // Bind the briefing renderer to the real period lifecycle.
        // Production USF (usf-engine.js) exposes an eventBus and emits
        // 'period:submitted' (after the period advances) and 'period:undone'
        // (after Undo decrements the period). We re-render the briefing on both,
        // reading the *live* currentPeriod so the shown round always matches the
        // round being graded. Falls back to button clicks for engines with no
        // eventBus (e.g. the self-contained standalone preview shim).
        _wireBriefingEvents() {
            if (this._briefingWired) return;
            var self = this;
            var fw = window.mySimulation;
            var render = function() {
                try { self._updateBriefing(window.mySimulation.state); } catch (e) {}
            };
            if (fw && fw.eventBus && typeof fw.eventBus.on === `function`) {
                fw.eventBus.on(`period:submitted`, render);
                fw.eventBus.on(`period:undone`, render);
                this._briefingWired = true;
            } else {
                [`nextPeriodBtn`, `undoBtn`].forEach(function(id) {
                    var btn = document.getElementById(id);
                    if (btn) {
                        btn.addEventListener(`click`, function() { setTimeout(render, 60); });
                    }
                });
                // Do not latch _briefingWired here: if the framework/eventBus becomes
                // available on a later initialize pass, prefer the event path.
            }
        }

        _wireSliderLabels() {
            var pairs = [
                [`onlinePctInput`, `onlinePctLabel`],
                [`weightIncomeInput`, `weightIncomeLabel`],
                [`intentionDiscountInput`, `intentionDiscountLabel`],
                [`growthAssumptionInput`, `growthLabel`],
                [`carrefourCaptureInput`, `captureLabel`]
            ];
            pairs.forEach(function(p) {
                var input = document.getElementById(p[0]);
                var label = document.getElementById(p[1]);
                if (input && label) {
                    label.textContent = input.value;
                    // Guard so we attach the input listener at most once per element
                    // (previously re-attached on every round change, leaking listeners).
                    if (input.dataset.qrLabelWired !== `1`) {
                        input.addEventListener(`input`, function() { label.textContent = input.value; });
                        input.dataset.qrLabelWired = `1`;
                    }
                }
            });
        }

        _updateBriefing(state) {
            var cp = (state && state.currentPeriod) || 1;
            var idx = Math.min(Math.max(cp - 1, 0), this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = window.mySimulation.t(round.nameKey);

            var briefEl = document.getElementById(`briefingText`);
            if (briefEl) briefEl.innerHTML = window.mySimulation.t(round.briefingKey);

            for (var i = 1; i <= 4; i++) {
                var p = document.getElementById(`panelRound` + i);
                if (p) p.style.display = (i === cp) ? `block` : `none`;
            }
            this._wireSliderLabels();
        }

        validateDecisions(decisions) {
            var cp = window.mySimulation.state.currentPeriod || 1;

            if (cp === 1) {
                var ss = document.getElementById(`sampleSizeInput`);
                var op = document.getElementById(`onlinePctInput`);
                var nq = document.getElementById(`neutralQuestionsInput`);
                if (ss) decisions.sampleSize = parseInt(ss.value);
                if (op) decisions.onlinePct = parseInt(op.value);
                if (nq) decisions.neutralQ = nq.value;

                var costPerOnline = 40000;
                var costPerInPerson = 120000;
                var onlineFrac = decisions.onlinePct / 100;
                var perInterviewCost = onlineFrac * costPerOnline + (1 - onlineFrac) * costPerInPerson;
                var totalCost = perInterviewCost * decisions.sampleSize;
                if (totalCost > 120000000 * 1.05) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t(`budget_warning`), `warning`
                    );
                    return false;
                }
            } else if (cp === 2) {
                var wi = document.getElementById(`weightIncomeInput`);
                var nr = document.getElementById(`nonResponseAdjInput`);
                var id = document.getElementById(`intentionDiscountInput`);
                if (wi) decisions.weightIncome = parseInt(wi.value);
                if (nr) decisions.nonResponseAdj = nr.value;
                if (id) decisions.intentionDiscount = parseInt(id.value);
            } else if (cp === 3) {
                var m = document.getElementById(`methodInput`);
                var g = document.getElementById(`growthAssumptionInput`);
                var cc = document.getElementById(`carrefourCaptureInput`);
                if (m) decisions.method = m.value;
                if (g) decisions.growthAssumption = parseInt(g.value);
                if (cc) decisions.carrefourCapture = parseInt(cc.value);
            } else if (cp === 4) {
                var r = document.getElementById(`recommendInput`);
                var c = document.getElementById(`confidenceInput`);
                var d = document.getElementById(`disclosureInput`);
                if (r) decisions.recommend = r.value;
                if (c) decisions.confidence = c.value;
                if (d) decisions.disclosure = d.value;
            }
            return true;
        }

        // Convert the domain outcome into a 0-100 score the platform can grade on.
        // credibility (0-150, higher = better) 55%, low bias (0-100, lower = better)
        // 30%, and — once a market estimate exists — how defensible it is 15%.
        // Before Round 3 (no estimate yet) the market term is dropped and the
        // remaining weights are renormalised to credibility 65% / bias 35%.
        _computeScore(ds) {
            var credComp = Math.max(0, Math.min(1, ds.credibility / 150));
            var biasComp = Math.max(0, Math.min(1, 1 - ds.biasIndex / 100));
            var m = ds.marketEstimate;
            var score;
            if (m > 0) {
                var marketComp;
                if (m >= 8000000000 && m <= 9500000000) marketComp = 1;        // bias-corrected, defensible
                else if (m >= 7000000000 && m <= 11000000000) marketComp = 0.55;
                else marketComp = 0.25;                                         // inflated / implausible
                score = 100 * (0.55 * credComp + 0.30 * biasComp + 0.15 * marketComp);
            } else {
                score = 100 * (0.65 * credComp + 0.35 * biasComp);
            }
            return Math.round(Math.max(0, Math.min(100, score)));
        }

        _letterGrade(s) {
            return s >= 85 ? `A` : s >= 70 ? `B` : s >= 55 ? `C` : s >= 40 ? `D` : `F`;
        }

        _perfTier(credibility, bias) {
            if (credibility >= 120 && bias <= 25) return `excelente`;
            if (credibility >= 90 && bias <= 40) return `solido`;
            if (credibility >= 65) return `aceptable`;
            return `principiante`;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var cp = state.currentPeriod;
            var credibilityDelta = 0;
            var biasDelta = 0;
            var marketEst = ds.marketEstimate;
            var costRound = 0;
            var notes = ``;

            if (cp === 1) {
                var costPerOnline = 40000;
                var costPerInPerson = 120000;
                var onlineFrac = d.onlinePct / 100;
                var perInterviewCost = onlineFrac * costPerOnline + (1 - onlineFrac) * costPerInPerson;
                costRound = Math.round(perInterviewCost * d.sampleSize);

                var sampleSizeScore = 0;
                if (d.sampleSize >= 1050) sampleSizeScore = 10;
                else if (d.sampleSize >= 600) sampleSizeScore = 4;

                var onlineBias = 0;
                if (d.onlinePct >= 70) onlineBias = 22;
                else if (d.onlinePct >= 50) onlineBias = 12;
                else if (d.onlinePct >= 30) onlineBias = 6;
                else onlineBias = 3;

                var questionBias = 0;
                if (d.neutralQ === `leading`) questionBias = 18;
                else if (d.neutralQ === `mixed`) questionBias = 8;
                else questionBias = 2;

                biasDelta = onlineBias + questionBias;
                credibilityDelta = sampleSizeScore - (onlineBias / 2) - (questionBias / 2);
                notes = `Sesgo de muestreo: ` + onlineBias + ` pts. Sesgo de pregunta: ` + questionBias + ` pts.`;
            } else if (cp === 2) {
                var weightingGain = 0;
                if (d.weightIncome >= 20 && d.weightIncome <= 30) weightingGain = 14;
                else if (d.weightIncome >= 10) weightingGain = 8;
                else if (d.weightIncome > 0) weightingGain = 3;
                else weightingGain = -6;

                var nrGain = 0;
                if (d.nonResponseAdj === `followup`) nrGain = 12;
                else if (d.nonResponseAdj === `reweight`) nrGain = 6;
                else nrGain = -5;

                var gapGain = 0;
                if (d.intentionDiscount >= 25 && d.intentionDiscount <= 45) gapGain = 16;
                else if (d.intentionDiscount >= 15) gapGain = 8;
                else if (d.intentionDiscount > 0) gapGain = 3;
                else gapGain = -8;

                credibilityDelta = weightingGain + nrGain + gapGain;
                biasDelta = -(weightingGain + nrGain + gapGain) / 2;
                notes = `Corrección por ponderación: ` + weightingGain + ` pts. Corrección no-respuesta: ` + nrGain + ` pts. Brecha intención: ` + gapGain + ` pts.`;
            } else if (cp === 3) {
                if (d.method === `A`) { marketEst = 11000000000; credibilityDelta = -4; }
                else if (d.method === `B`) { marketEst = 8500000000; credibilityDelta = 10; }
                else { marketEst = 11900000000; credibilityDelta = 2; }

                var growthPenalty = 0;
                if (d.growthAssumption >= 12 && d.growthAssumption <= 20) growthPenalty = 6;
                else if (d.growthAssumption > 25) growthPenalty = -10;
                else if (d.growthAssumption < 8) growthPenalty = -4;

                var capturePenalty = 0;
                if (d.carrefourCapture >= 15 && d.carrefourCapture <= 30) capturePenalty = 6;
                else if (d.carrefourCapture > 45) capturePenalty = -10;
                else capturePenalty = -2;

                credibilityDelta += growthPenalty + capturePenalty;
                biasDelta = (d.method === `A` ? 10 : (d.method === `C` ? 12 : -4));
                notes = `Método ` + d.method + `. Crecimiento ` + d.growthAssumption + `%. Captura ` + d.carrefourCapture + `%.`;
            } else if (cp === 4) {
                var recScore = 0;
                if (d.recommend === `invest_partial`) recScore = 14;
                else if (d.recommend === `defer`) recScore = 8;
                else if (d.recommend === `invest_full`) recScore = -6;
                else recScore = -2;

                var confScore = 0;
                if (d.confidence === `balanced`) confScore = 10;
                else if (d.confidence === `cautious`) confScore = 6;
                else confScore = -10;

                var discScore = 0;
                if (d.disclosure === `full`) discScore = 12;
                else if (d.disclosure === `partial`) discScore = 4;
                else discScore = -14;

                credibilityDelta = recScore + confScore + discScore;
                biasDelta = -(confScore + discScore) / 2;
                notes = `Recomendación: ` + d.recommend + `. Confianza: ` + d.confidence + `. Divulgación: ` + d.disclosure + `.`;
            }

            ds.credibility = Math.max(0, Math.min(150, ds.credibility + credibilityDelta));
            ds.biasIndex = Math.max(0, Math.min(100, ds.biasIndex + biasDelta));
            ds.marketEstimate = marketEst;
            ds.budgetUsed += costRound;

            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.biasHistory.push(Math.round(ds.biasIndex));
            ds.marketHistory.push(marketEst);

            // ── Scoring for the platform reporting/grading layer ──────────────
            // express_extractMetrics() reads domainState.performance.overallScore /
            // .grade for the instructor Score column and the LTI grade passback;
            // express_extractHistory() reads the same path inside each history
            // snapshot for the per-round progression. Writing it here (before the
            // engine snapshots domainState into history and persists PERIOD_END)
            // populates every read path. Mirrored into results.* as a belt-and-braces
            // fallback (extractHistory routes 3-6).
            var overallScore = this._computeScore(ds);
            var grade = this._letterGrade(overallScore);
            ds.performance = { overallScore: overallScore, grade: grade };

            var results = {
                period: cp,
                credibilityDelta: Math.round(credibilityDelta * 10) / 10,
                biasDelta: Math.round(biasDelta * 10) / 10,
                credibility: Math.round(ds.credibility),
                biasIndex: Math.round(ds.biasIndex),
                marketEstimate: marketEst,
                costRound: costRound,
                overallScore: overallScore,
                score: overallScore,
                grade: grade,
                notes: notes
            };

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`,
                (v) => Math.round(v) + ` / 150`);
            uiManager.bind(`biasDisplay`, `domainState.biasIndex`,
                (v) => Math.round(v) + ` / 100`);
            uiManager.bind(`marketDisplay`, `domainState.marketEstimate`,
                (v) => v > 0 ? (`COP ` + (v / 1000000000).toFixed(1) + `B`) : `—`);
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`,
                (v) => `COP ` + (v / 1000000).toFixed(0) + `M`);
        }

        getChartConfig() {
            var t = (k) => window.mySimulation.t(k);
            return {
                credibilityChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [{
                            label: t(`chart_cred_series`),
                            data: [],
                            borderColor: `#003893`,
                            backgroundColor: `rgba(0,56,147,0.12)`,
                            borderWidth: 3,
                            fill: true,
                            tension: 0.2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t(`chart_cred_title`) } },
                        scales: { y: { beginAtZero: true, max: 150 } }
                    }
                },
                biasChart: {
                    type: `bar`,
                    data: {
                        labels: [],
                        datasets: [{
                            label: t(`chart_bias_series`),
                            data: [],
                            backgroundColor: `rgba(193,39,45,0.7)`,
                            borderColor: `#c1272d`,
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: t(`chart_bias_title`) } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var t = (k) => window.mySimulation.t(k);
            var labels = state.domainState.credibilityHistory.map((_, i) => `R` + (i + 1));
            return {
                credibilityChart: {
                    labels: labels,
                    datasets: [{ label: t(`chart_cred_series`), data: state.domainState.credibilityHistory }]
                },
                biasChart: {
                    labels: labels,
                    datasets: [{ label: t(`chart_bias_series`), data: state.domainState.biasHistory }]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            // Gate on the round that was just computed (results.period) rather than
            // state.currentPeriod, which the engine has already advanced by now —
            // otherwise the round-2 and method-A hints never fired at a useful time.
            var justPlayed = results.period || state.currentPeriod;
            if (results.credibility < 60) return window.mySimulation.t(`hint_low_cred`);
            if (results.biasIndex > 40) return window.mySimulation.t(`hint_high_bias`);
            if (justPlayed === 1 && state.decisions.intentionDiscount === 0) return window.mySimulation.t(`hint_gap`);
            if (justPlayed === 3 && state.decisions.method === `A`) return window.mySimulation.t(`hint_method_a`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Ronda`, i18nKey: `col_round` },
                { key: `results.credibilityDelta`, label: `Δ Credibilidad`, i18nKey: `col_cred_delta` },
                { key: `results.biasDelta`, label: `Δ Sesgo`, i18nKey: `col_bias_delta` },
                { key: `results.credibility`, label: `Credibilidad`, i18nKey: `col_credibility` },
